#!/usr/bin/env bash
# CFC-3 (openspec change cross-file-consistency-gates): the chart grants at least what the
# kustomize role grants.
#
# config/rbac/role.yaml is generated by controller-gen from the +kubebuilder:rbac markers; the
# chart's manager roles (templates/clusterrole.yaml, role.yaml, role-leader-election.yaml; the
# metrics-reader role is not one) are written by hand. A marker that adds a permission updates
# role.yaml on `make manifests` and leaves the chart behind, so a Helm install is Forbidden where
# a kustomize install works. This gate expands both sides into (apiGroup, resource, verb)
# triples and fails on every role.yaml triple the rendered manager roles do not grant.
#
# What it locks:
#   * `helm template` with default values: the rendered manager ClusterRole(s) grant every
#     role.yaml triple, except lines of mode `default` in
#     hack/test/testdata/consistency-rbac-exceptions.txt. role.yaml is a ClusterRole, so a
#     namespaced Role (leader election, release namespace only) never stands in for it;
#   * `helm template --set tenantMode=true`: the rendered manager Role(s) grant every role.yaml
#     triple except lines of mode `tenant`: cluster-scoped triples (reason class
#     `cluster-scoped:`; a kollect.dev kind must be a Cluster-scoped CRD in config/crd/bases, any
#     other resource a known cluster-scoped built-in) and workload-collection reads (class
#     `team-workload:`, get/list/watch of a kind in TEAM_WORKLOAD_KINDS), which tenant mode
#     leaves to the team (docs/examples/team-operator.md §3). A Role never covers a
#     cluster-scoped resource (RBAC ignores it there). Any other namespaced triple missing from
#     the tenant Role fails;
#   * the exceptions carry the mode on each line, so a tenant-only exception cannot excuse a gap
#     in the default render; every line needs a reason; a line the render does not need (stale)
#     fails;
#   * a rule with resourceNames covers nothing (it grants named objects only); `*` matches all;
#   * an empty scan -- no role.yaml rules, or no manager role rendered -- fails, never passes.
# Chart-only grants (the chart is a superset) are out of scope: CFC-3 is one-way.
#
# Usage:
#   hack/test/consistency_rbac_test.sh              # check the repository tree
#   hack/test/consistency_rbac_test.sh --self-test  # mutate copies, assert each check fails
#   hack/test/consistency_rbac_test.sh <tree-root>  # check an arbitrary tree root
set -euo pipefail

fail() {
  echo "FAIL: $*" >&2
  exit 1
}

pass() {
  echo "ok - $*"
}

SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"

MODE="check"
if [[ "${1:-}" == "--self-test" ]]; then
  MODE="self-test"
  shift
fi

ROOT="${1:-}"
if [[ -z "${ROOT}" ]]; then
  ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
fi
ROOT="${ROOT%/}"

command -v helm >/dev/null 2>&1 || fail "helm not found; install helm to run this test"
python3 -c 'import yaml' 2>/dev/null || fail "python3 with PyYAML not found; install it to run this test"

EXCEPTIONS_REL="hack/test/testdata/consistency-rbac-exceptions.txt"

check_rbac() {
  local root="$1"
  python3 - "${root}" "${EXCEPTIONS_REL}" <<'PY'
import glob
import subprocess
import sys

import yaml

root, exceptions_rel = sys.argv[1], sys.argv[2]
MANAGER_TEMPLATES = ("clusterrole.yaml", "role.yaml", "role-leader-election.yaml")
MODES = {"default": [], "tenant": ["--set", "tenantMode=true"]}
# The role kind that may cover role.yaml's triples in each render: the default install is
# cluster-wide (role.yaml is a ClusterRole), the tenant install is namespaced by design.
COVERING_KIND = {"default": "ClusterRole", "tenant": "Role"}
# Workload kinds a KollectTarget collects whose reads tenant mode leaves to the team (CFC-3 as
# amended 2026-10-15, docs/examples/team-operator.md §3). A closed list, so a reconciler need
# (secrets, configmaps, events, kollect.dev kinds) cannot be filed as team workload: a new
# workload marker means extending this set in a reviewed change to the gate and the spec.
TEAM_WORKLOAD_KINDS = {("apps", "deployments"), ("cert-manager.io", "certificates")}
READ_VERBS = {"get", "list", "watch"}
# Built-in resources that are cluster-scoped (Kubernetes API facts), the only non-kollect.dev
# resources a tenant `cluster-scoped:` exception may name. kollect.dev kinds are read from the
# CRDs instead. Extend this only with a resource the API serves without a namespace.
CLUSTER_SCOPED_BUILTINS = {
    ("", "namespaces"), ("", "nodes"), ("", "persistentvolumes"),
    ("authentication.k8s.io", "tokenreviews"), ("authentication.k8s.io", "selfsubjectreviews"),
    ("authorization.k8s.io", "subjectaccessreviews"),
    ("authorization.k8s.io", "selfsubjectaccessreviews"),
    ("authorization.k8s.io", "selfsubjectrulesreviews"),
    ("rbac.authorization.k8s.io", "clusterroles"),
    ("rbac.authorization.k8s.io", "clusterrolebindings"),
    ("apiextensions.k8s.io", "customresourcedefinitions"),
    ("admissionregistration.k8s.io", "mutatingwebhookconfigurations"),
    ("admissionregistration.k8s.io", "validatingwebhookconfigurations"),
    ("storage.k8s.io", "storageclasses"),
}
errors = []


def show(t):
    g, r, v = t
    return f"{g or 'core'} {r} {v}"


def rule_triples(rules):
    out = set()
    for rule in rules or []:
        for g in rule.get("apiGroups") or []:
            for res in rule.get("resources") or []:
                for v in rule.get("verbs") or []:
                    out.add((g, res, v))
    return out


def is_cluster_scoped(g, r):
    base = (g, r.split("/")[0])
    if g == "kollect.dev":
        return crd_scope.get(base) == "Cluster"
    return base in CLUSTER_SCOPED_BUILTINS


def covers(rules, t, kind):
    g, r, v = t
    if kind == "Role" and is_cluster_scoped(g, r):
        return False
    for rule in rules:
        if rule.get("resourceNames"):
            continue
        if (g in (rule.get("apiGroups") or []) or "*" in (rule.get("apiGroups") or [])) and \
           (r in (rule.get("resources") or []) or "*" in (rule.get("resources") or [])) and \
           (v in (rule.get("verbs") or []) or "*" in (rule.get("verbs") or [])):
            return True
    return False


# --- want: every triple of config/rbac/role.yaml (all documents) ---
role_path = f"{root}/config/rbac/role.yaml"
want = set()
with open(role_path) as fh:
    for doc in yaml.safe_load_all(fh):
        if doc:
            want |= rule_triples(doc.get("rules"))
if not want:
    print(f"FAIL: config/rbac/role.yaml yields no (apiGroup, resource, verb) triple -- an empty scan never passes", file=sys.stderr)
    sys.exit(1)

# --- kollect.dev CRD scopes, by plural ---
crd_scope = {}
for path in sorted(glob.glob(f"{root}/config/crd/bases/*.yaml")):
    with open(path) as fh:
        for doc in yaml.safe_load_all(fh):
            if doc and doc.get("kind") == "CustomResourceDefinition":
                spec = doc.get("spec") or {}
                crd_scope[(spec.get("group"), (spec.get("names") or {}).get("plural"))] = spec.get("scope")

# --- exceptions ---
exceptions = {}  # (mode, triple) -> line number
exc_path = f"{root}/{exceptions_rel}"
try:
    exc_lines = open(exc_path).read().splitlines()
except FileNotFoundError:
    exc_lines = []
    errors.append(f"{exceptions_rel} is missing")
for n, raw in enumerate(exc_lines, 1):
    line = raw.strip()
    if not line or line.startswith("#"):
        continue
    where = f"{exceptions_rel}:{n}"
    fields = line.split(None, 4)
    if len(fields) < 5 or not fields[4].strip():
        errors.append(f"{where}: exception has no reason ('{line}') -- every line is <mode> <apiGroup> <resource> <verb> <reason>")
        continue
    mode, group, resource, verb, reason = fields
    if mode not in MODES:
        errors.append(f"{where}: unknown mode '{mode}' (expected one of: {', '.join(MODES)})")
        continue
    t = ("" if group == "core" else group, resource, verb)
    base = (t[0], resource.split("/")[0])
    if mode == "tenant":
        if reason.startswith("cluster-scoped:"):
            if t[0] == "kollect.dev":
                if crd_scope.get(base) != "Cluster":
                    errors.append(f"{where}: {show(t)} is marked cluster-scoped but config/crd/bases has no Cluster-scoped CRD {base[1]} (scope: {crd_scope.get(base)})")
                    continue
            elif base not in CLUSTER_SCOPED_BUILTINS:
                errors.append(f"{where}: {show(t)} is marked cluster-scoped but {base[0] or 'core'}/{base[1]} is not a known cluster-scoped resource")
                continue
        elif reason.startswith("team-workload:"):
            if (t[0], resource) not in TEAM_WORKLOAD_KINDS or verb not in READ_VERBS:
                errors.append(f"{where}: {show(t)} is marked team-workload but only get/list/watch of a kind in TEAM_WORKLOAD_KINDS can be")
                continue
        else:
            errors.append(f"{where}: a tenant exception's reason must start with 'cluster-scoped:' or 'team-workload:' ('{reason}')")
            continue
    key = (mode, t)
    if key in exceptions:
        errors.append(f"{where}: duplicate of line {exceptions[key]}")
        continue
    exceptions[key] = n

# --- render and compare, per mode ---
for mode, args in MODES.items():
    cmd = ["helm", "template", "kollect", f"{root}/charts/kollect", "--namespace", "kollect-system", *args]
    res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode != 0:
        errors.append(f"{mode}: helm template failed: {res.stderr.strip()[:300]}")
        continue
    rules, roles = [], []
    # Not --show-only: it errors when a template renders nothing (clusterrole.yaml in tenant
    # mode). Render everything and keep the documents whose "# Source:" is a manager template.
    for chunk in res.stdout.split("\n---"):
        src = None
        for line in chunk.splitlines():
            if line.startswith("# Source: "):
                src = line[len("# Source: "):].strip()
        if not src or not any(src.endswith("/templates/" + t) for t in MANAGER_TEMPLATES):
            continue
        doc = yaml.safe_load(chunk)
        if not doc or doc.get("kind") != COVERING_KIND[mode]:
            continue
        roles.append(f"{doc['kind']} {doc['metadata']['name']}")
        rules += doc.get("rules") or []
    if not roles:
        errors.append(f"{mode}: the chart rendered no manager {COVERING_KIND[mode]} -- an empty scan never passes")
        continue
    used, before = set(), len(errors)
    for t in sorted(want):
        if covers(rules, t, COVERING_KIND[mode]):
            continue
        if (mode, t) in exceptions:
            used.add((mode, t))
            continue
        hint = " (cluster-scoped: a Role cannot grant it)" if COVERING_KIND[mode] == "Role" and is_cluster_scoped(t[0], t[1]) else ""
        errors.append(f"{mode}: role.yaml grants {show(t)} but the chart's manager roles ({', '.join(roles)}) do not{hint}")
    for (m, t), n in sorted(exceptions.items(), key=lambda kv: kv[1]):
        if m == mode and (m, t) not in used:
            why = "the chart grants it" if covers(rules, t, COVERING_KIND[mode]) else "role.yaml does not grant it"
            errors.append(f"{exceptions_rel}:{n}: stale {mode} exception {show(t)} -- {why}")
    if len(errors) == before:
        print(f"ok - {mode}: {len(want)} role.yaml triples, {len(used)} excepted, rendered {', '.join(roles)}")

for e in errors:
    print(f"FAIL: {e}", file=sys.stderr)
sys.exit(1 if errors else 0)
PY
}

if [[ "${MODE}" == "check" ]]; then
  if check_rbac "${ROOT}"; then
    pass "the chart's manager roles grant every config/rbac/role.yaml triple, in default and tenant mode, outside the listed exceptions"
    exit 0
  fi
  fail "the chart grants less than config/rbac/role.yaml (listed above) -- a Helm install would be Forbidden where a kustomize install works"
fi

# ---------------------------------------------------------------------------
# Self-test (CFC-6): copy the files the gate reads, break one invariant per copy, and assert
# the gate reds WITH THE MESSAGE of the assertion the mutant targets -- a non-zero exit alone
# is not evidence. One unmutated copy must pass.
# ---------------------------------------------------------------------------
SCRATCH=""
trap 'rm -rf ${SCRATCH} 2>/dev/null' EXIT

make_copy() {
  local dst="$1"
  mkdir -p "${dst}/config/rbac" "${dst}/config/crd" "${dst}/charts" "${dst}/hack/test/testdata"
  cp "${ROOT}/config/rbac/role.yaml" "${dst}/config/rbac/"
  cp -R "${ROOT}/config/crd/bases" "${dst}/config/crd/bases"
  cp -R "${ROOT}/charts/kollect" "${dst}/charts/kollect"
  cp "${ROOT}/${EXCEPTIONS_REL}" "${dst}/${EXCEPTIONS_REL}"
}

# Called directly (never as $(new_copy)), so SCRATCH survives in this shell for the EXIT trap.
COPY=""
new_copy() {
  COPY="$(mktemp -d)"
  SCRATCH="${SCRATCH} ${COPY}"
  make_copy "${COPY}"
}

# mutant_rejected <label> <sentinel> <probe-regex> <probe-file> <command...>
# The command runs inside the copy; the probe proves the mutation landed before the gate runs.
# The probe ABSENT asserts that <probe-file> no longer exists.
mutant_rejected() {
  local label="$1" sentinel="$2" probe="$3" probe_file="$4"
  shift 4
  local out rc
  new_copy
  (cd "${COPY}" && "$@") ||
    fail "self-test: the mutation step for '${label}' failed -- nothing was tested"
  if [[ "${probe}" == "ABSENT" ]]; then
    [[ ! -e "${COPY}/${probe_file}" ]] ||
      fail "self-test: the '${label}' mutant did not land (${probe_file} still exists) -- nothing was tested"
  else
    grep -Eq -- "${probe}" "${COPY}/${probe_file}" ||
      fail "self-test: the '${label}' mutant did not land (no '${probe}' in ${probe_file}) -- nothing was tested"
  fi
  out="$(bash "${SELF}" "${COPY}" 2>&1)" && rc=0 || rc=$?
  [[ "${rc}" -ne 0 ]] ||
    fail "self-test: the gate accepted the '${label}' mutant (exit 0) -- the assertion '${sentinel}' did not fire"
  grep -Fq -- "${sentinel}" <<<"${out}" ||
    fail "self-test: the '${label}' mutant red for the WRONG reason; expected '${sentinel}', got: $(grep FAIL <<<"${out}" | head -3 | tr '\n' ' ')"
  pass "self-test: ${label} rejected with '${sentinel}'"
}

# No-op control: an unmutated copy passes. Also proves the gate reads the root it is given.
new_copy
if ! out="$(bash "${SELF}" "${COPY}" 2>&1)"; then
  fail "self-test: the no-op control failed on an unmutated copy -- fix the real tree (or the gate) first: $(grep FAIL <<<"${out}" | head -3 | tr '\n' ' ')"
fi
pass "self-test: no-op control passes on an unmutated copy"

EXC="${EXCEPTIONS_REL}"
CR="charts/kollect/templates/clusterrole.yaml"
TR="charts/kollect/templates/role.yaml"

# A +kubebuilder:rbac marker adds a permission; `make manifests` updates role.yaml, the chart
# is not touched. Both renders lack it; the default one is the scenario.
mutant_rejected "marker adds a permission the chart lacks" \
  "default: role.yaml grants kollect.dev kollectwidgets get but the chart's manager roles" \
  'kollectwidgets' config/rbac/role.yaml \
  bash -c 'printf -- "- apiGroups:\n  - kollect.dev\n  resources:\n  - kollectwidgets\n  verbs:\n  - get\n" >> config/rbac/role.yaml'

# A triple dropped from the default ClusterRole template.
mutant_rejected "triple removed from the default render" \
  "default: role.yaml grants authentication.k8s.io tokenreviews create but" \
  'resources: \[tokenreviews\]' "${CR}" \
  sed -i -E '/apiGroups: \[authentication\.k8s\.io\]/,/verbs:/ s/verbs: \[create\]/verbs: [get]/' "${CR}"

mutant_rejected "exception without a reason" \
  "exception has no reason" '^tenant apps deployments get$' "${EXC}" \
  sed -i -E 's/^(tenant apps deployments get) .*/\1/' "${EXC}"

mutant_rejected "exception without a reason, trailing blanks" \
  "exception has no reason" '^tenant apps deployments list[[:space:]]+$' "${EXC}" \
  sed -i -E 's/^(tenant apps deployments list) .*/\1   /' "${EXC}"

# deployments get/list/watch is excused in tenant mode only. Dropping it from the default
# ClusterRole must red the default render: the tenant line does not reach across modes.
mutant_rejected "tenant-only exception does not excuse a default-mode gap" \
  "default: role.yaml grants apps deployments get but" \
  'resources: \[deployments\]' "${CR}" \
  sed -i -E '/apiGroups: \[apps\]/,/verbs:/ s/verbs: \[.*\]/verbs: [create, delete, patch, update]/' "${CR}"

# A new namespaced, non-workload reconciler grant: role.yaml and the default ClusterRole gain
# it, the tenant Role does not. Default passes; tenant must red.
mutant_rejected "new namespaced non-workload triple missing in tenant mode" \
  "tenant: role.yaml grants core persistentvolumeclaims get but" \
  'persistentvolumeclaims' "${CR}" \
  bash -c 'printf -- "- apiGroups:\n  - \"\"\n  resources:\n  - persistentvolumeclaims\n  verbs:\n  - get\n" >> config/rbac/role.yaml &&
    sed -i -E "s/resources: \[configmaps, namespaces, secrets\]/resources: [configmaps, namespaces, secrets, persistentvolumeclaims]/" '"${CR}"

# An existing reconciler grant dropped from the tenant Role.
mutant_rejected "tenant Role drops a namespaced reconciler grant" \
  "tenant: role.yaml grants core secrets get but" \
  'resources: \[configmaps\]' "${TR}" \
  sed -i -E 's/resources: \[secrets\]/resources: [configmaps]/' "${TR}"

# ...and excusing it as cluster-scoped is refused: secrets are namespaced.
mutant_rejected "namespaced built-in excused as cluster-scoped" \
  "core secrets get is marked cluster-scoped but core/secrets is not a known cluster-scoped resource" \
  '^tenant core secrets get' "${EXC}" \
  bash -c 'sed -i -E "s/resources: \[secrets\]/resources: [configmaps]/" '"${TR}"' &&
    printf "tenant core secrets get cluster-scoped: wrong\n" >> '"${EXC}"

mutant_rejected "namespaced kollect.dev kind excused as cluster-scoped" \
  "kollect.dev kollecttargets get is marked cluster-scoped but config/crd/bases has no Cluster-scoped CRD kollecttargets" \
  '^tenant kollect.dev kollecttargets get' "${EXC}" \
  bash -c 'printf "tenant kollect.dev kollecttargets get cluster-scoped: wrong\n" >> '"${EXC}"

mutant_rejected "write verb excused as team workload" \
  "core secrets create is marked team-workload but only get/list/watch of a kind in TEAM_WORKLOAD_KINDS" \
  '^tenant core secrets create' "${EXC}" \
  bash -c 'printf "tenant core secrets create team-workload: wrong\n" >> '"${EXC}"

# A reconciler read (secrets) dropped from the tenant Role and filed as team workload: refused,
# team-workload is a closed list of collected kinds.
mutant_rejected "reconciler read excused as team workload" \
  "core secrets get is marked team-workload but only get/list/watch of a kind in TEAM_WORKLOAD_KINDS" \
  '^tenant core secrets get team-workload' "${EXC}" \
  bash -c 'sed -i -E "s/resources: \[secrets\]/resources: [configmaps]/" '"${TR}"' &&
    printf "tenant core secrets get team-workload: x\ntenant core secrets list team-workload: x\ntenant core secrets watch team-workload: x\n" >> '"${EXC}"

mutant_rejected "tenant exception without a class" \
  "a tenant exception's reason must start with 'cluster-scoped:' or 'team-workload:'" \
  'because' "${EXC}" \
  sed -i -E 's/^(tenant apps deployments watch) team-workload:/\1 because/' "${EXC}"

mutant_rejected "unknown mode" \
  "unknown mode 'tenants'" '^tenants ' "${EXC}" \
  sed -i -E 's/^tenant (apps deployments get)/tenants \1/' "${EXC}"

mutant_rejected "duplicate exception" \
  "duplicate of line" '^tenant apps deployments get' "${EXC}" \
  bash -c 'grep -E "^tenant apps deployments get " '"${EXC}"' > dup.tmp && cat dup.tmp >> '"${EXC}"

# The chart now grants deployments read in tenant mode: the tenant exceptions for it are stale.
mutant_rejected "stale exception, chart grants the triple" \
  "stale tenant exception apps deployments get -- the chart grants it" \
  'apiGroups: \[apps\]' "${TR}" \
  sed -i -E 's/^(rules:)$/\1\n  - apiGroups: [apps]\n    resources: [deployments]\n    verbs: [get, list, watch]/' "${TR}"

mutant_rejected "stale exception, role.yaml no longer grants it" \
  "stale tenant exception cert-manager.io certificates get -- role.yaml does not grant it" \
  '^  - certificatez$' config/rbac/role.yaml \
  sed -i -E 's/^  - certificates$/  - certificatez/' config/rbac/role.yaml

# A default-mode line excuses only the default render: the gap it covers stays red in tenant
# mode, so the default line itself is not stale and the tenant render names the triple.
mutant_rejected "default-only exception does not excuse a tenant-mode gap" \
  "tenant: role.yaml grants core secrets get but" \
  '^default core secrets get' "${EXC}" \
  bash -c 'sed -i -E "s/resources: \[configmaps, namespaces, secrets\]/resources: [configmaps, namespaces]/; s/resources: \[secrets\]/resources: [configmaps]/" '"${CR}"' '"${TR}"' &&
    printf "default core secrets get example\ndefault core secrets list example\ndefault core secrets watch example\n" >> '"${EXC}"

mutant_rejected "missing exceptions file" \
  "${EXC} is missing" ABSENT "${EXC}" \
  rm "${EXC}"

mutant_rejected "empty role.yaml scan" \
  "config/rbac/role.yaml yields no (apiGroup, resource, verb) triple" '^rules: \[\]$' config/rbac/role.yaml \
  bash -c 'printf -- "---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata:\n  name: manager-role\nrules: []\n" > config/rbac/role.yaml'

# role-leader-election.yaml is not gated on rbac.create, so turning RBAC off still renders a
# manager Role; removing the three manager templates is what leaves the scan empty.
mutant_rejected "no manager role rendered" \
  "default: the chart rendered no manager ClusterRole" ABSENT "${CR}" \
  rm "${CR}" "${TR}" charts/kollect/templates/role-leader-election.yaml

mutant_rejected "rule restricted by resourceNames covers nothing" \
  "default: role.yaml grants authentication.k8s.io tokenreviews create but" \
  'resourceNames: \[only-this\]' "${CR}" \
  sed -i -E 's/^(    resources: \[tokenreviews\])$/\1\n    resourceNames: [only-this]/' "${CR}"

# role.yaml is a ClusterRole: the namespaced leader-election Role (configmaps, events in the
# release namespace only) must not stand in for the ClusterRole in the default render.
mutant_rejected "leader-election Role does not stand in for the ClusterRole" \
  "default: role.yaml grants core configmaps get but" \
  'resources: \[namespaces, secrets\]' "${CR}" \
  sed -i -E 's/resources: \[configmaps, namespaces, secrets\]/resources: [namespaces, secrets]/' "${CR}"

# The tenant manager role must be a Role (its RoleBinding binds a Role); a ClusterRole rendered
# in its place covers nothing in tenant mode.
mutant_rejected "tenant manager Role rendered as a ClusterRole" \
  "tenant: role.yaml grants core secrets get but" \
  '^kind: ClusterRole$' "${TR}" \
  sed -i -E 's/^kind: Role$/kind: ClusterRole/' "${TR}"

# A Role cannot grant a cluster-scoped resource: listing namespaces in the tenant Role does not
# make the namespaces exceptions stale, and deleting them reds the tenant render.
mutant_rejected "Role does not cover a cluster-scoped resource" \
  "tenant: role.yaml grants core namespaces get but the chart's manager roles (Role kollect-leader-election, Role kollect-manager) do not (cluster-scoped: a Role cannot grant it)" \
  'resources: \[secrets, namespaces\]' "${TR}" \
  bash -c 'sed -i -E "s/resources: \[secrets\]/resources: [secrets, namespaces]/" '"${TR}"' &&
    sed -i -E "/^tenant core namespaces /d" '"${EXC}"

# Green control: a default-mode exception excuses a real default-mode gap (the mechanism the
# spec allows), and a wildcard verb covers every verb.
control_passes() {
  local label="$1" probe="$2" probe_file="$3"
  shift 3
  local out
  new_copy
  (cd "${COPY}" && "$@") || fail "self-test: the control step for '${label}' failed -- nothing was tested"
  grep -Eq -- "${probe}" "${COPY}/${probe_file}" ||
    fail "self-test: the '${label}' control did not land (no '${probe}' in ${probe_file})"
  out="$(bash "${SELF}" "${COPY}" 2>&1)" ||
    fail "self-test: the gate red on the '${label}' control -- it must pass: $(grep FAIL <<<"${out}" | head -2 | tr '\n' ' ')"
  pass "self-test: ${label} control passes"
}

control_passes "default exception excuses a default gap" '^default authentication\.k8s\.io tokenreviews create ' "${EXC}" \
  bash -c 'sed -i -E "/apiGroups: \[authentication\.k8s\.io\]/,/verbs:/ s/verbs: \[create\]/verbs: [get]/" '"${CR}"' &&
    printf "default authentication.k8s.io tokenreviews create example reason\n" >> '"${EXC}"

control_passes "wildcard verb covers every verb" 'verbs: \["\*"\]' "${CR}" \
  sed -i -E '/apiGroups: \[authentication\.k8s\.io\]/,/verbs:/ s/verbs: \[create\]/verbs: ["*"]/' "${CR}"

echo "All RBAC consistency self-tests passed."
